package com.aditya.fefo.unit;
import com.aditya.fefo.domain.*; import com.aditya.fefo.domain.allocator.*; import org.junit.jupiter.api.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class FefoAllocatorTest { Product p=new Product("SKU","Milk",""); @Test void ordersByProvidedExpiryAndSplits(){var a=new Batch(p,"A",LocalDate.now().plusDays(2),50);var b=new Batch(p,"B",LocalDate.now().plusDays(5),100);var out=FefoAllocator.allocate(List.of(a,b),120);assertEquals(List.of(50L,70L),out.stream().map(Allocation::quantity).toList());} @Test void rejectsInsufficient(){var a=new Batch(p,"A",LocalDate.now().plusDays(2),50);assertThrows(IllegalArgumentException.class,()->FefoAllocator.allocate(List.of(a),51));} @Test void skipsExpired(){assertThrows(IllegalArgumentException.class,()->new Batch(p,"A",LocalDate.now().minusDays(1),50));}}

